import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { acquireModel, type ModelLease } from '../utils/modelCache';
import { beginModelLoad, endModelLoad } from '../utils/modelLoading';
import { isAppIdle, subscribeAppIdle } from '../utils/idleSleep';

// Plain three.js renderer — deliberately NOT @react-three/fiber: fiber 9
// (via its `its-fine` dependency) statically references React.use, which
// React 18 does not export, so importing fiber breaks the production
// build outright (webpack: "'use' is not exported from 'react'").
// Plain three.js compiles and runs fine on React 18.
//
// The model is framed by its own bounding box: Tripo GLBs arrive at
// arbitrary scale and offset, so the scene re-scales to ~1.8 units tall
// (times `zoom`) and re-centres on the origin.
//
// FULL-BOX FIT (Round 16, Eddie 2026-11-17: "Prime Zero's wings are
// clipped off; some of the other 3D models have clipped wings as
// well"): the camera used to sit at one fixed distance, and the
// hand-tuned `zoom` values on the wide-wing models (Emberwing 1.45,
// Ashwing 1.5, Voltwing 1.3) pushed their wingspans PAST the frame
// — measured at phone aspect, Emberwing's box filled 134% of the
// frame width. The camera now auto-fits: after a model loads, its
// scaled bounding box (horizontal extent as a yaw-proof cylinder
// radius, so the in-scene sway can never swing a wingtip out of
// frame) sets a minimum camera distance at the canvas's real
// aspect, with the arena's 0.94 fit margin. The camera only ever
// dollies BACK from the classic framing, never closer — models
// that already fit render exactly as before, and `zoom` still
// enlarges a model, with the fit as the guarantee that the
// enlargement stops at the frame's edge instead of past it.
//
// PRESENTATION LAW (Eddie, 2026-11-16): a navitar stands UPRIGHT on
// its base, facing front. It may only turn LEFT ↔ RIGHT — a gentle
// in-scene yaw sway of the model group, oscillating within
// ±yawAmpDeg of front on a sine (eased at both ends by the sine
// itself). NEVER a full rotation, NEVER a card-flip, and NEVER
// grab-and-orbit: this viewer has no orbit controls at all — the
// camera framing is the game's, not the user's. (The first version
// had OrbitControls + a continuous 360° turntable; both are gone.)
// The sway is time-based, not frame-based, so it keeps its tempo at
// any frame rate, and it stands down entirely under
// prefers-reduced-motion.
//
// STANDING BASE (same law): every model stands on the soft
// contact shadow under its feet, grounded exactly at the model's
// min.y (no floating, no sinking). QC verified 2026-11-16 that no
// model has a base baked into its GLB (Tidefang's "wave block" and
// Shadowmaw's "smoke base" are portrait-only paint). A model whose
// pose calls for it (Tidefang's coil) can be seated slightly INTO
// the ground via sinkFrac — see utils/navitarArt
// modelPresentationFor.
//
// SHADOW ONLY, NO DISC (Round 36.5 began it on the two stages;
// Round 36.9 Part 3, Eddie 2026-11-20, completes it EVERYWHERE):
// the element-tinted podium disc and its water ripple ring are
// retired on every surface — Stage, shelf, grid, Profile, AR,
// Home. "We should just move to straight shadow no disc." The
// battle arena's ground is a different renderer entirely
// (ElementalWorld), untouched.
//
// PERSISTENT CANVAS + PARSED-MODEL CACHE (Round 36.22, the 36.21
// freeze fix): two changes share this file. (1) The model comes
// from utils/modelCache as a LEASED CLONE — each GLB is parsed
// once per session; a mount clones the parsed scene instead of
// re-parsing the bytes on the main thread. (2) The renderer,
// scene, camera and WebGL context are built ONCE per canvas
// (the stage effect below) and the model swaps INSIDE them (the
// model effect): on a fighter change the outgoing model stays
// standing until the incoming clone is in hand, then the swap
// is one remove + one add. Before this, every fighter change
// tore the whole canvas down (context force-lost) and the next
// fighter's first render paid a fresh context's full shader
// compiles + texture uploads — in the verify VM that alone was
// a ~10 s main-thread task on a cache-WARM swap. In one living
// context, a warm fighter's textures and programs are already
// resident, so the swap is the clone and nothing else.

// The canvas's long-lived stage: built once by the stage effect,
// read by the render loop, and re-stood by the model effect on
// every fighter change.
interface CanvasStage {
  renderer: THREE.WebGLRenderer;
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  fitBox: { cylR: number; halfH: number; targetY: number } | null;
  applyFit: () => void;
  model: THREE.Group | null;
  // Rigged-model life (Round 36.14): the 29 original GLBs carry
  // NO animation clips (verified: single merged meshes, zero
  // skins), so `mixer` stays null for them and their presentation
  // is exactly the sway it always was. A model WITH a genuine
  // idle clip (the pilot rigs) gets a mixer that plays ONLY that
  // clip — walk/attack clips are never looped as a fake idle
  // (Prime Zero's rig carries walk only, so he keeps the standard
  // presentation, honestly).
  mixer: THREE.AnimationMixer | null;
  companion: THREE.Group | null;
  companionBaseY: number;
  shadowMesh: THREE.Mesh | null;
  shadowTexture: THREE.Texture;
  mainLease: ModelLease | null;
  companionLease: ModelLease | null;
  // Round 36.32: the GL context died (see the stage effect's
  // context handlers). While set, the loop stands down and model
  // stands complete silently — the owner covers the slot with
  // art until the post-restore rebuild stands the fighter again.
  contextLost: boolean;
  // Round 36.32: a render throw already demoted this stage —
  // the demotion (owner's onError) fires exactly once per stage.
  renderFailed: boolean;
  // The standing model's own sway, captured when it stood — so a
  // held fighter keeps swaying in ITS way (its facing correction
  // and signature tempo) while the next fighter travels, never
  // snapping to the incoming fighter's values early.
  sway: { amp: number; period: number; phase: number; facing: number };
  prevTickT: number;
  startedAt: number;
  reducedMotion: boolean;
}

const ModelCanvas: React.FC<{
  modelUrl: string;
  // Companion model (Round 36.14): a second GLB that shares this
  // scene, hovering at the main model's shoulder — the Multiverse
  // Bot's sphere drone. Opt-in per caller; absent, the scene is
  // exactly the single-model scene it always was. The companion
  // is presentation only: it never affects loading state (the
  // main model's onLoaded/onError stay the surface's truth), and
  // a companion that fails to load simply never appears.
  companionUrl?: string;
  // Closer framing for models whose bounding box is dominated by a wide
  // span (the phoenix's wings), which otherwise reads small in the card.
  zoom?: number;
  // Grounded framing (run 2 add-on fix): instead of centring the
  // bounding box, plant the model's feet (box.min.y) at the ground
  // and aim the camera at its mid-height, so in the AR view it
  // STANDS on the ground shadow instead of floating at frame centre.
  // Card viewers omit it and keep the centred framing.
  grounded?: boolean;
  // Yaw sway (presentation law above): amplitude in degrees either
  // side of front, one full left-right-left cycle in yawPeriodS
  // seconds, phase-shifted by yawPhaseS so fighters never sway in
  // sync. Defaults are a gentle ±14° / 9s for plain viewer use; the
  // Navidex Stage passes its per-fighter signature values.
  yawAmpDeg?: number;
  yawPeriodS?: number;
  yawPhaseS?: number;
  // Standing-base tint (element colour, from the caller's palette).
  baseTint?: string;
  // Bare-shadow standing: since Round 36.9 every standing is
  // bare-shadow; the prop remains accepted for caller
  // compatibility and no longer changes what renders.
  bareShadow?: boolean;
  // Water presentation: the ripple ring retired with the disc in
  // Round 36.9; accepted for compatibility, renders nothing.
  ripple?: boolean;
  // Facing correction (radians): Tripo models disagree on which
  // way is front — the caller's presentation registry
  // (utils/navitarArt modelPresentationFor) supplies the yaw that
  // faces this model at the camera. The sway oscillates AROUND it.
  rotationY?: number;
  // Seating: sink the model into its disc by this fraction of its
  // scaled height (Tidefang's coil, ~0.04) so it reads as rising
  // out of the disc rather than balancing on it.
  sinkFrac?: number;
  // Render activity (Round 36.9 Part 7b): when false, the render
  // loop stands DOWN — no rAF, no render — while the scene, the
  // loaded model and the WebGL context stay mounted, so flipping
  // back to active is instant. The Navidex Stage passes
  // active={the 3D face is showing}: in Card mode the canvas used
  // to keep rendering under the card art (battery audit §2).
  // Loading is unaffected — a model still loads and the
  // sanctioned prefetch still warms while inactive.
  active?: boolean;
  // Context loss (Round 36.32): onContextLost fires when this
  // canvas's WebGL context is lost; onContextRestored fires when
  // the browser restores it and a fresh stage is being built.
  // Owners cover the slot with the fighter's art on either event
  // and keep it covered until the next onLoaded — a model is
  // only ever presented while it is truly standing.
  onContextLost?: () => void;
  onContextRestored?: () => void;
  onLoaded: () => void;
  onError: () => void;
}> = ({
  modelUrl,
  companionUrl,
  zoom = 1,
  grounded = false,
  yawAmpDeg = 14,
  yawPeriodS = 9,
  yawPhaseS = 0,
  baseTint = '#12a5c7',
  bareShadow = false,
  ripple = false,
  rotationY = 0,
  sinkFrac = 0,
  active = true,
  onContextLost,
  onContextRestored,
  onLoaded,
  onError,
}) => {
  const mountRef = useRef<HTMLDivElement>(null);
  // Latest props, read by the long-lived effects/tick without
  // re-running the scene setup when a caller re-renders.
  const propsRef = useRef({
    onLoaded,
    onError,
    onContextLost,
    onContextRestored,
    yawAmpDeg,
    yawPeriodS,
    yawPhaseS,
    baseTint,
    bareShadow,
    ripple,
    rotationY,
    sinkFrac,
    active,
  });
  propsRef.current = {
    onLoaded,
    onError,
    onContextLost,
    onContextRestored,
    yawAmpDeg,
    yawPeriodS,
    yawPhaseS,
    baseTint,
    bareShadow,
    ripple,
    rotationY,
    sinkFrac,
    active,
  };
  // Round 36.32: the stage's generation. A restored GL context
  // bumps it, and the stage + model effects rebuild from scratch
  // on a fresh canvas/context — recovery never leans on the
  // half-dead stage's internals.
  const [glEpoch, setGlEpoch] = useState(0);
  const stageRef = useRef<CanvasStage | null>(null);
  // The stage effect registers its loop-restarter here so the
  // `active` prop (and the idle-sleep wake) can stand the render
  // loop back up without re-running the scene setup.
  const resumeRef = useRef<(() => void) | null>(null);
  useEffect(() => {
    if (active) resumeRef.current?.();
  }, [active]);

  // ---- The stage (Round 36.22): renderer, scene, camera,
  // lights and the render loop are built ONCE per canvas and
  // live across every fighter change; only the model swaps
  // (the model effect below). The full teardown — lease
  // releases and the context release — happens here, once, at
  // real unmount. ----
  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    let raf = 0;
    let cancelled = false;
    let renderer: THREE.WebGLRenderer | null = null;

    try {
      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    } catch {
      propsRef.current.onError();
      return;
    }
    // Round 36.32 — THE CRASH, disarmed at its root: on a
    // program's first use, three.js (r175 WebGLProgram
    // onFirstUse) reads gl.getProgramInfoLog(..).trim() and
    // gl.getShaderInfoLog(..).trim() to report shader errors.
    // On a DEAD context WebKit returns NULL from those calls,
    // so the error-reporting path itself throws "null is not an
    // object (evaluating 'a.getShaderInfoLog(x).trim')" — and
    // because this canvas renders synchronously inside React
    // effect flushes (the active-resume below), that TypeError
    // climbed straight to the route error boundary and took the
    // whole Navidex page down (Eddie's screenshot, 2026-11-28).
    // The log read is a debug aid only; our materials are
    // three's built-ins. Turning it off makes this exact throw
    // impossible, whatever the context does. (The context-loss
    // handling and the render guard below are the other two
    // layers — a dead context must still degrade to art, never
    // to an error page.)
    renderer.debug.checkShaderErrors = false;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(mount.clientWidth, mount.clientHeight);
    renderer.setClearColor(0x000000, 0);
    mount.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      42,
      mount.clientWidth / Math.max(mount.clientHeight, 1),
      0.1,
      100
    );
    camera.position.set(0, 0.4, 3.4);
    // No orbit controls (presentation law): the camera is aimed
    // once, at the framing target — the old code let OrbitControls
    // re-aim it every frame; the grounded branch re-aims at the
    // model's mid-height once the box is known.
    camera.lookAt(0, 0, 0);

    // Soft radial contact shadow texture (drawn once per canvas):
    // a dark centre fading to nothing — the ground-grip under the
    // model's feet, on the podium disc or straight on the field.
    // Each standing's shadow PLANE is built from it per model
    // (the plane's size is per-model) by the model effect.
    const shadowTexture = (() => {
      const c = document.createElement('canvas');
      c.width = 128;
      c.height = 128;
      const ctx = c.getContext('2d');
      if (ctx) {
        const g = ctx.createRadialGradient(64, 64, 4, 64, 64, 62);
        g.addColorStop(0, 'rgba(0,0,0,0.55)');
        g.addColorStop(0.6, 'rgba(0,0,0,0.28)');
        g.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, 128, 128);
      }
      const tex = new THREE.CanvasTexture(c);
      return tex;
    })();

    const stage: CanvasStage = {
      renderer,
      scene,
      camera,
      fitBox: null,
      applyFit: () => undefined,
      model: null,
      mixer: null,
      companion: null,
      companionBaseY: 0,
      shadowMesh: null,
      shadowTexture,
      mainLease: null,
      companionLease: null,
      contextLost: false,
      renderFailed: false,
      sway: {
        amp: propsRef.current.yawAmpDeg,
        period: propsRef.current.yawPeriodS,
        phase: propsRef.current.yawPhaseS,
        facing: propsRef.current.rotationY,
      },
      prevTickT: 0,
      startedAt: performance.now(),
      reducedMotion:
        typeof window !== 'undefined' &&
        typeof window.matchMedia === 'function' &&
        window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    };

    // ---- Full-box camera fit (Round 16, see header) -----------
    // The classic framing: target at the origin (or the grounded
    // model's mid-height), camera on the (0, 0.4, 3.4) ray. The
    // fit keeps that ray and only extends its length when the
    // loaded model's bounding box demands it.
    const FIT_DIR = new THREE.Vector3(0, 0.4, 3.4);
    const FIT_DEFAULT_DIST = FIT_DIR.length();
    FIT_DIR.normalize();
    const FIT_MARGIN = 0.9; // the arena's fit margin (ElementalWorld);
    // Round 36.9 Part 1: tightened from 0.94 — the full model bounds,
    // wingspan included, frame with a visible margin of air around
    // them (Eddie: "we give room for them to have full wings").
    stage.applyFit = () => {
      const fitBox = stage.fitBox;
      if (!fitBox || !mount) return;
      const aspect = mount.clientWidth / Math.max(mount.clientHeight, 1);
      camera.aspect = aspect;
      const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
      const tanH = tanV * aspect;
      // Distance at which the box's nearest face plane clears
      // both frustum axes: the cylinder radius must fit the
      // horizontal angle, the half-height the vertical, each
      // measured from (distance − radius) so the model's nearest
      // point is what clears the frame.
      const needed =
        fitBox.cylR +
        Math.max(fitBox.halfH / (tanV * FIT_MARGIN), fitBox.cylR / (tanH * FIT_MARGIN));
      const dist = Math.max(FIT_DEFAULT_DIST, needed);
      camera.position.set(FIT_DIR.x * dist, fitBox.targetY + FIT_DIR.y * dist, FIT_DIR.z * dist);
      camera.lookAt(0, fitBox.targetY, 0);
      camera.updateProjectionMatrix();
    };

    scene.add(new THREE.AmbientLight(0xffffff, 0.9));
    const key = new THREE.DirectionalLight(0xffffff, 1.4);
    key.position.set(3, 5, 4);
    scene.add(key);
    const fill = new THREE.DirectionalLight(0xffffff, 0.4);
    fill.position.set(-4, 2, -3);
    scene.add(fill);

    stageRef.current = stage;

    const onResize = () => {
      if (!mount || !renderer) return;
      const w = mount.clientWidth;
      const h = Math.max(mount.clientHeight, 1);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
      // The fit is aspect-dependent (Round 16): a narrower canvas
      // needs the camera further back for the same box.
      stage.applyFit();
    };
    window.addEventListener('resize', onResize);
    // Round 36.8: the stage card's focus mode resizes the
    // canvas's CONTAINER without any window resize — observe
    // the mount so the renderer size and the aspect fit
    // follow the box. Idempotent at the standing size.
    const mountObserver =
      typeof ResizeObserver !== 'undefined' ? new ResizeObserver(onResize) : null;
    if (mountObserver && mount) mountObserver.observe(mount);

    // The render loop (Round 36.9 Part 7b + 7e): the loop runs
    // only while this canvas is ACTIVE (its face is the one
    // showing) and the app is AWAKE. Standing down stops the
    // rAF chain entirely — no per-frame JS, no render — while
    // the scene and model stay mounted for an instant return.
    // The sway is time-based, so a resumed loop picks up the
    // correct phase with no jump.
    let loopRunning = false;
    const tick = () => {
      if (cancelled || stage.contextLost || !propsRef.current.active || isAppIdle()) {
        loopRunning = false;
        return;
      }
      loopRunning = true;
      raf = requestAnimationFrame(tick);
      const t = (performance.now() - stage.startedAt) / 1000;
      const model = stage.model;
      if (model) {
        // The yaw sway (presentation law): the MODEL GROUP turns
        // left ↔ right in-scene around its facing correction,
        // sinusoidal — full speed mid-swing, easing to a stop at
        // each end, always upright, never beyond ±amp of front,
        // never a full turn. Reduced motion: holds the correction.
        // The values are the STANDING model's own, captured when
        // it stood (stage.sway) — a held fighter never snaps to
        // the incoming fighter's sway early.
        const { amp, period, phase, facing } = stage.sway;
        model.rotation.y =
          facing +
          (stage.reducedMotion
            ? 0
            : THREE.MathUtils.degToRad(amp) *
              Math.sin(((t + phase) / Math.max(period, 0.1)) * Math.PI * 2));
      }
      // Round 36.14: advance the rigged idle (delta-clamped so a
      // resumed loop never lurches) and hover the companion. Both
      // stand down under reduced motion, like the sway.
      if (stage.mixer && !stage.reducedMotion) {
        stage.mixer.update(Math.min(Math.max(t - stage.prevTickT, 0), 0.1));
      }
      stage.prevTickT = t;
      if (stage.companion) {
        stage.companion.position.y =
          stage.companionBaseY + (stage.reducedMotion ? 0 : Math.sin(t * 1.6) * 0.045);
      }
      if (renderer && scene) {
        try {
          renderer.render(scene, camera);
        } catch (err) {
          // Round 36.32: NO throw from the 3D layer ever escapes
          // this loop. tick() runs inside React effect flushes
          // (the stage setup and the active-resume both call it
          // synchronously), so an uncaught render throw is a
          // route-boundary page death — that is exactly how a
          // dead GL context killed the Navidex (see the
          // checkShaderErrors note at renderer creation). Demote
          // instead: stop the loop and hand the slot to the
          // owner, which stands the fighter's art in its place.
          loopRunning = false;
          cancelAnimationFrame(raf);
          if (!stage.renderFailed) {
            stage.renderFailed = true;
            console.warn('ModelCanvas: render failed — demoting this fighter to its art:', err);
            propsRef.current.onError();
          }
        }
      }
    };
    const startLoop = () => {
      if (cancelled || loopRunning) return;
      loopRunning = true;
      tick();
    };
    resumeRef.current = startLoop;
    // Idle-sleep wake: stand back up the moment the app wakes.
    const unsubscribeIdle = subscribeAppIdle(sleeping => {
      if (!sleeping) startLoop();
    });

    // ---- Context loss (Round 36.32) ---------------------------
    // iOS revokes WebGL contexts under GPU/memory pressure —
    // on this app's first heavyweight render (a fresh Navidex
    // open hydrating a full collection while a 26 MB fighter
    // parses and uploads) that is a when, not an if. The loss
    // itself is survivable by design: preventDefault keeps the
    // context restorable (three's own handler does the same),
    // the loop stands down, and the owner covers the slot with
    // the fighter's CARD ART — the card-match law's sanctioned
    // cover: a model is presented only while it is truly that
    // fighter standing there, and on a dead context it is not
    // standing there. On restore we do NOT try to revive this
    // stage's half-dead GL state: the epoch bump rebuilds the
    // whole stage on a fresh canvas/context (this effect's
    // teardown + setup, the paths every fighter change already
    // trusts), and the model effect re-runs with it and stands
    // the fighter again — its onLoaded lifts the owner's cover.
    const onGlContextLost = (e: Event) => {
      e.preventDefault();
      stage.contextLost = true;
      loopRunning = false;
      cancelAnimationFrame(raf);
      propsRef.current.onContextLost?.();
    };
    const onGlContextRestored = () => {
      if (cancelled) return;
      propsRef.current.onContextRestored?.();
      setGlEpoch(n => n + 1);
    };
    renderer.domElement.addEventListener('webglcontextlost', onGlContextLost);
    renderer.domElement.addEventListener('webglcontextrestored', onGlContextRestored);
    tick();

    return () => {
      cancelled = true;
      unsubscribeIdle();
      renderer?.domElement.removeEventListener('webglcontextlost', onGlContextLost);
      renderer?.domElement.removeEventListener('webglcontextrestored', onGlContextRestored);
      if (resumeRef.current === startLoop) resumeRef.current = null;
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', onResize);
      mountObserver?.disconnect();
      // The standing model and companion are leased CLONES from
      // the parsed-model cache — detached and RELEASED, never
      // disposed (their geometry/materials are shared with the
      // cache master). The traverse then disposes only what this
      // canvas created itself (the shadow plane).
      if (stage.mixer) {
        stage.mixer.stopAllAction();
        stage.mixer = null;
      }
      if (stage.model) {
        scene.remove(stage.model);
        stage.model = null;
      }
      if (stage.companion) {
        scene.remove(stage.companion);
        stage.companion = null;
      }
      if (stage.mainLease) {
        stage.mainLease.release();
        stage.mainLease = null;
      }
      if (stage.companionLease) {
        stage.companionLease.release();
        stage.companionLease = null;
      }
      scene.traverse(obj => {
        const mesh = obj as THREE.Mesh;
        if (mesh.geometry) mesh.geometry.dispose();
        const material = mesh.material as THREE.Material | THREE.Material[] | undefined;
        if (Array.isArray(material)) material.forEach(m => m.dispose());
        else if (material) material.dispose();
      });
      shadowTexture.dispose();
      if (stageRef.current === stage) stageRef.current = null;
      renderer?.dispose();
      // Actually RELEASE the WebGL context (Round 6 fix): dispose()
      // alone leaves the context alive until the browser's lazy GC,
      // and mobile Safari caps live contexts (~8) — swiping a
      // roster of 3D fighters used to exhaust them, after which
      // new renderer creation threw and fighters fell back to
      // portraits for the rest of the session. Round 36.22: this
      // now happens ONCE per canvas unmount, not per fighter —
      // the canvas (and its context) persists across fighters.
      renderer?.forceContextLoss();
      if (renderer && mount.contains(renderer.domElement)) {
        mount.removeChild(renderer.domElement);
      }
    };
    // Round 36.32: the epoch is the context-restore rebuild —
    // see onGlContextRestored above. Ordinary mounts run once.
  }, [glEpoch]);

  // ---- The model (Round 36.22): stands the requested fighter
  // inside the persistent stage, swap-on-ready — the outgoing
  // model stays standing until the incoming clone is in hand,
  // so a fighter change never shows an empty slot. Runs on
  // mount and on every model change; its cleanup does NOT tear
  // the standing model down (the next stand, an error, or the
  // stage teardown above does). ----
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return;
    let stale = false;
    let retryTimer = 0;
    let loadAttempts = 0;
    // Round 24: this load registers with the global model-loading
    // registry (utils/modelLoading) — the ambient slowdown and the
    // summon surfaces read it. Settled exactly once: on load, on
    // final error, or on supersede/unmount, whichever comes first
    // (the retry below does NOT settle — the model is still
    // travelling).
    let loadSettled = false;
    const settleLoad = () => {
      if (!loadSettled) {
        loadSettled = true;
        endModelLoad();
      }
    };

    // Take the standing model (and its companion + shadow) out
    // of the scene and hand its leases back to the cache.
    const teardownModel = () => {
      if (stage.mixer) {
        stage.mixer.stopAllAction();
        stage.mixer = null;
      }
      if (stage.model) {
        stage.scene.remove(stage.model);
        stage.model = null;
      }
      if (stage.companion) {
        stage.scene.remove(stage.companion);
        stage.companion = null;
      }
      if (stage.shadowMesh) {
        stage.scene.remove(stage.shadowMesh);
        stage.shadowMesh.geometry.dispose();
        const m = stage.shadowMesh.material as THREE.Material | THREE.Material[];
        if (Array.isArray(m)) m.forEach(x => x.dispose());
        else m.dispose();
        stage.shadowMesh = null;
      }
      if (stage.mainLease) {
        stage.mainLease.release();
        stage.mainLease = null;
      }
      if (stage.companionLease) {
        stage.companionLease.release();
        stage.companionLease = null;
      }
      stage.fitBox = null;
    };

    const loadModel = () => {
      acquireModel(modelUrl).then(
        lease => {
          if (stale) {
            lease.release();
            return;
          }
          if (stage.contextLost) {
            // Round 36.32: the context died while this fighter
            // travelled. Do NOT stand it and do NOT report it
            // loaded — the slot stays on the owner's art cover.
            // When the context restores, the stage rebuild
            // re-runs this effect and the fighter stands then.
            lease.release();
            settleLoad();
            return;
          }
          // Swap-on-ready: the previous fighter stood until
          // this instant — now it steps down and the new one
          // stands in the same scene, same context.
          teardownModel();
          stage.mainLease = lease;
          const gltf = { scene: lease.scene, animations: lease.animations };
          const { scene, camera } = stage;
          const box = new THREE.Box3().setFromObject(gltf.scene);
          const size = box.getSize(new THREE.Vector3());
          const center = box.getCenter(new THREE.Vector3());
          const max = Math.max(size.x, size.y, size.z) || 1;
          const scale = (1.8 * zoom) / max;
          gltf.scene.scale.setScalar(scale);
          if (grounded) {
            // Feet at y=0 (min.y grounding, the battle-stage rule),
            // camera raised to the model's mid-height: a ~1.8-unit
            // model in the ~2.6-unit view lands its feet ~85% down
            // the frame, on its podium disc.
            gltf.scene.position.set(-center.x * scale, -box.min.y * scale, -center.z * scale);
            const midY = (size.y * scale) / 2;
            camera.position.set(0, midY + 0.4, 3.4);
            camera.lookAt(0, midY, 0);
          } else {
            gltf.scene.position.set(-center.x * scale, -center.y * scale, -center.z * scale);
          }
          // Seating (presentation registry): sink the model into
          // its disc by sinkFrac of its scaled height — the disc
          // top stays on the ground plane, the model's lowest
          // point settles just below it.
          const sink = propsRef.current.sinkFrac * size.y * scale;
          if (sink > 0) gltf.scene.position.y -= sink;
          // Full-box fit (Round 16): record the scaled bounding
          // box — horizontal extent as a yaw-proof cylinder
          // radius (the sway rotates the model in-scene; the
          // cylinder is the widest the box can ever project) —
          // and frame the camera on it. The grounded branch's
          // hand-set camera above is the default this fit starts
          // from and only extends. The sink lowers the box, so
          // it joins the half-height the fit must clear.
          stage.fitBox = {
            cylR: Math.hypot((size.x * scale) / 2, (size.z * scale) / 2),
            halfH: (size.y * scale) / 2 + sink,
            targetY: grounded ? (size.y * scale) / 2 : 0,
          };
          stage.applyFit();
          // Facing: the model's rest yaw is its correction; the
          // tick's sway oscillates around this value.
          gltf.scene.rotation.y = propsRef.current.rotationY;
          // Capture this model's own sway for the tick (see
          // stage.sway): the standing model moves in its own way
          // for as long as it stands, held swaps included.
          stage.sway = {
            amp: propsRef.current.yawAmpDeg,
            period: propsRef.current.yawPeriodS,
            phase: propsRef.current.yawPhaseS,
            facing: propsRef.current.rotationY,
          };
          stage.model = gltf.scene;
          scene.add(gltf.scene);

          // ---- Rigged idle (Round 36.14) ----------------------
          // A genuinely rigged model with an IDLE clip plays it —
          // the bones move, the group sway above still rides on
          // top, exactly as it does for the static originals. The
          // clip search is name-based and conservative: a clip
          // must SAY idle; walk/slash/attack clips never qualify,
          // so no fighter fakes an idle it doesn't have. One
          // update(0) lands the clip's first frame immediately,
          // so even a reduced-motion viewer (whose tick never
          // advances the mixer) sees the idle pose, not bind pose.
          const idleClip = (gltf.animations || []).find(a => /idle/i.test(a.name || ''));
          if (idleClip) {
            stage.mixer = new THREE.AnimationMixer(gltf.scene);
            stage.mixer.clipAction(idleClip).play();
            stage.mixer.update(0);
          }

          // ---- Companion (Round 36.14) ------------------------
          // Loaded only after the main model stands, so its
          // shoulder seat is measured from the main model's real
          // frame. It hovers at the model's right (the viewer's
          // right, where the Bot's art carries its drone), sized
          // to ~0.42 scene units, with a gentle hover bob in the
          // tick. The camera fit widens to keep it in frame.
          if (companionUrl) {
            acquireModel(companionUrl).then(
              clease => {
                if (stale) {
                  clease.release();
                  return;
                }
                stage.companionLease = clease;
                const cgltf = { scene: clease.scene };
                const cbox = new THREE.Box3().setFromObject(cgltf.scene);
                const csize = cbox.getSize(new THREE.Vector3());
                const ccenter = cbox.getCenter(new THREE.Vector3());
                const cmax = Math.max(csize.x, csize.y, csize.z) || 1;
                const cscale = 0.42 / cmax;
                cgltf.scene.scale.setScalar(cscale);
                const compX = (size.x * scale) / 2 + 0.34;
                const compY = grounded ? size.y * scale * 0.82 : size.y * scale * 0.32;
                cgltf.scene.position.set(
                  compX - ccenter.x * cscale,
                  compY - ccenter.y * cscale,
                  0.05 - ccenter.z * cscale
                );
                stage.companion = cgltf.scene;
                stage.companionBaseY = cgltf.scene.position.y;
                scene.add(cgltf.scene);
                if (stage.fitBox) {
                  stage.fitBox.cylR = Math.max(stage.fitBox.cylR, compX + 0.21);
                  stage.fitBox.halfH = Math.max(
                    stage.fitBox.halfH,
                    compY + 0.21 - stage.fitBox.targetY
                  );
                  stage.applyFit();
                }
              },
              () => {
                // A companion that fails simply never appears —
                // the main model's standing is unaffected.
              }
            );
          }

          // ---- Standing base -----------------------------------
          // The model's feet in scene space: y=0 when grounded,
          // the bottom of the centred box otherwise. The base sits
          // exactly there — disc top flush with min.y.
          const feetY = grounded ? 0 : -(size.y * scale) / 2;
          const footSpan = Math.max(size.x, size.z) * scale;
          const radius = Math.min(Math.max(footSpan * 0.575, 0.55), 1.4);

          // The contact shadow is EVERY standing's ground-grip —
          // and since Round 36.9 it is the ONLY base: no disc,
          // no ripple ring, on any surface.
          const shadow = new THREE.Mesh(
            new THREE.PlaneGeometry(radius * 2.1, radius * 2.1),
            new THREE.MeshBasicMaterial({
              map: stage.shadowTexture,
              transparent: true,
              depthWrite: false,
            })
          );
          shadow.rotation.x = -Math.PI / 2;
          shadow.position.y = feetY + 0.002;
          shadow.renderOrder = 1;
          stage.shadowMesh = shadow;
          scene.add(shadow);

          // Round 36.9 Part 3 (Eddie, 2026-11-20): SHADOW ONLY,
          // NO DISC, EVERYWHERE. The podium disc and its water
          // ripple ring are RETIRED on every surface — grid and
          // shelf cards, Profile, AR, Home, Stage — not just the
          // bare-shadow stages that went first in Round 36.5.
          // Eddie: "sometimes we have the character on a disc and
          // sometimes we have the character on a shadow. I think
          // we should just move to straight shadow no disc." The
          // contact shadow above is now the ONLY standing base.
          // The bareShadow / ripple props stay in the API for
          // caller compatibility; they no longer change what
          // renders. (The battle arena floor is the realm's
          // ground in ElementalWorld, a different renderer —
          // untouched, as before.)

          settleLoad();
          propsRef.current.onLoaded();
        },
        () => {
          if (stale) return;
          // ONE automatic retry before giving up (2026-11-16,
          // Round 6): these GLBs run up to ~28 MB — a single
          // network hiccup on a phone used to mark the fighter as
          // "picture forever". A transient failure now heals
          // itself; only a second failure reports the error.
          loadAttempts += 1;
          if (loadAttempts <= 1) {
            retryTimer = window.setTimeout(loadModel, 700);
          } else {
            // The incoming model truly failed: the slot empties
            // (the held fighter steps down with it) and the
            // caller stands its portrait in the slot, exactly as
            // the old teardown-first canvas behaved on error.
            teardownModel();
            settleLoad();
            propsRef.current.onError();
          }
        }
      );
    };
    beginModelLoad();
    loadModel();

    return () => {
      stale = true;
      window.clearTimeout(retryTimer);
      settleLoad();
    };
    // glEpoch (Round 36.32): a context restore rebuilt the
    // stage — re-stand the current fighter inside the new one.
  }, [modelUrl, companionUrl, zoom, grounded, glEpoch]);

  return <div ref={mountRef} style={{ width: '100%', height: '100%' }} />;
};

export default ModelCanvas;
