// Parsed-model cache (Round 36.22, Eddie 2026-11-25 — the
// battle-entry freeze fix; diagnosis: r3621-verify/REPORT.md).
//
// THE DEFECT this kills: until now there was NO parsed-model
// cache anywhere. Every mount of a modeled fighter — the
// Navidex Stage canvas (keyed per fighter, so every swipe was a
// full teardown), the deck cards' 3D face, the battle arena's
// buildFighter — built a brand-new GLTFLoader and re-parsed the
// GLB from bytes ON THE MAIN THREAD. A parse is seconds of
// synchronous work (Solara ~7.7 s of blocked heartbeat in the
// VM; the Multiverse Bot worst of all, chaining a second parse
// for its Sphere Drone). On a phone that reads as a frozen
// screen: taps, navigation and animation simply do not run
// while it happens.
//
// THE FIX: parse each model URL exactly once per session and
// keep the parsed scene as a pristine MASTER that is never
// added to a live scene. Every mount takes a LEASE: a
// SkeletonUtils clone of the master (geometry / materials /
// textures shared with the master and sibling clones; the
// clone's root carries the instance's own transform, and a
// rigged model's idle clip binds to the clone's bones by name,
// so Bot's idle and Prime Zero's walk-only rig behave exactly
// as they did on a fresh parse). Consumers release the lease
// when they unmount instead of disposing the model's resources
// — the cache owns disposal.
//
// CACHE DISCIPLINE (the old force-dispose cleanup was guarding
// phone memory; the freeze must not be traded for an OOM): at
// most CACHE_CAP masters are retained, LRU-evicted. An evicted
// master is disposed (geometry / materials / textures) as soon
// as its last live clone is released — never out from under a
// standing fighter.
//
// GPU DISCIPLINE (Round 36.31, Eddie 2026-11-27 — the Navidex
// swipe pile-up): the CPU cap above was NOT the phone's
// problem. A parsed master that has been RENDERED holds its
// textures and geometry buffers in the GPU memory of every
// canvas that showed it (a typical fighter ≈ 64 MB of textures
// + ~14 MB of buffers; the Griffin ≈ 271 MB). Masters stayed
// GPU-resident until LRU eviction, so swiping the deck walked
// fighter after fighter into graphics memory — a few swipes
// in, iOS killed the page ("A problem repeatedly occurred",
// Eddie's screenshot, "after I swipe a couple fighters"). The
// parse cache is not the pile-up; the un-released GPU uploads
// are.
//
// THE FIX: when a model's LAST lease is released, its GPU
// resources are released too — geometry.dispose() +
// texture.dispose() on the master frees the GPU buffers and
// texture images in EVERY context that uploaded them, while
// the CPU-side parsed data (attribute arrays, decoded texture
// images) stays in the master, untouched. A later acquire
// re-clones instantly (no re-parse — the 36.22 freeze stays
// dead) and three.js re-uploads from that CPU data on the
// first render (its per-renderer texture/geometry properties
// were removed by the dispose, so the version check simply
// uploads again — verified against the three r175 source).
// Materials are deliberately NOT disposed: their programs are
// small, shared across fighters, and disposing them would tax
// every return with shader recompiles for no memory that
// matters.
//
// ONE SPARE: the most recently released model may KEEP its
// GPU resources, so the common swipe-back (A → B → A) is
// instant — but only when its measured footprint fits
// SPARE_GPU_CAP. The Griffin-class monsters release
// immediately. Net effect while swiping: per canvas, the
// standing fighter plus at most one capped spare — flat, no
// matter how deep the swipe goes.
//
// This module imports three.js, so it must only ever be reached
// from the lazy 3D chunks (ModelCanvas, ElementalWorld) or via
// the dynamic import in utils/modelPrefetch — never statically
// from the main bundle.
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { clone as skeletonClone } from 'three/examples/jsm/utils/SkeletonUtils.js';

export interface ParsedModel {
  scene: THREE.Group;
  animations: THREE.AnimationClip[];
}

export interface ModelLease {
  // A clone of the cached master — yours to transform, add to a
  // scene, and animate. Never dispose its geometry/materials;
  // release() hands the accounting back to the cache.
  scene: THREE.Group;
  animations: THREE.AnimationClip[];
  release: () => void;
}

const CACHE_CAP = 6;

// Round 36.31: the one GPU spare (see header) may keep at most
// this many bytes resident. Sized from the roster census: a
// typical fighter measures ~78 MB (64 MB textures + ~14 MB
// geometry buffers) and the Multiverse Bot ~87 MB, so both
// stay spare-eligible; the Griffin (~271 MB) never does.
const SPARE_GPU_CAP = 96 * 1024 * 1024;

interface CacheEntry {
  promise: Promise<ParsedModel>;
  parsed: ParsedModel | null;
  live: number; // clones currently handed out
  waiters: number; // acquires in flight against a pending parse
  stale: boolean; // evicted from the map: dispose once free
  gpuBytes: number; // measured GPU footprint (textures + geometry)
  gpuReleased: boolean; // GPU resources released, CPU master kept
}

const entries = new Map<string, CacheEntry>();
const loader = new GLTFLoader();

// Every texture a scene's materials reference, in any slot
// (map, normalMap, roughnessMap, …), de-duplicated — the
// pre-36.31 disposal only freed `.map`, silently leaving the
// other slots' textures resident on the eviction path too.
function collectTextures(parsed: ParsedModel, into: Set<THREE.Texture>): void {
  parsed.scene.traverse(obj => {
    const mesh = obj as THREE.Mesh;
    const material = mesh.material as THREE.Material | THREE.Material[] | undefined;
    const scan = (m: THREE.Material) => {
      for (const key of Object.keys(m)) {
        const value = (m as unknown as Record<string, unknown>)[key];
        if (value && (value as THREE.Texture).isTexture) into.add(value as THREE.Texture);
      }
    };
    if (Array.isArray(material)) material.forEach(scan);
    else if (material) scan(material);
  });
}

function collectGeometries(parsed: ParsedModel, into: Set<THREE.BufferGeometry>): void {
  parsed.scene.traverse(obj => {
    const mesh = obj as THREE.Mesh;
    if (mesh.geometry) into.add(mesh.geometry);
  });
}

// Estimated GPU bytes for a parsed model: textures at
// RGBA + full mip chain (the R36.29 census method — it matched
// the measured footprints: Griffin 256 MB, a typical fighter
// 64 MB) plus geometry buffer bytes.
function estimateGpuBytes(parsed: ParsedModel): number {
  const textures = new Set<THREE.Texture>();
  collectTextures(parsed, textures);
  let bytes = 0;
  for (const tex of textures) {
    const image = tex.image as { width?: number; height?: number } | undefined;
    const w = image?.width ?? 0;
    const h = image?.height ?? 0;
    if (!w || !h) continue;
    let size = w * h * 4;
    const pot = (n: number) => (n & (n - 1)) === 0;
    if (tex.generateMipmaps && pot(w) && pot(h)) size = (size * 4) / 3;
    bytes += size;
  }
  const geometries = new Set<THREE.BufferGeometry>();
  collectGeometries(parsed, geometries);
  for (const geometry of geometries) {
    for (const name of Object.keys(geometry.attributes)) {
      bytes += geometry.attributes[name].array.byteLength;
    }
    if (geometry.index) bytes += geometry.index.array.byteLength;
  }
  return bytes;
}

// Full disposal for the eviction path: GPU resources AND the
// materials go, and the caller drops the CPU master itself.
function disposeParsed(parsed: ParsedModel): void {
  const geometries = new Set<THREE.BufferGeometry>();
  collectGeometries(parsed, geometries);
  geometries.forEach(g => g.dispose());
  const textures = new Set<THREE.Texture>();
  collectTextures(parsed, textures);
  textures.forEach(t => t.dispose());
  parsed.scene.traverse(obj => {
    const mesh = obj as THREE.Mesh;
    const material = mesh.material as THREE.Material | THREE.Material[] | undefined;
    if (Array.isArray(material)) material.forEach(m => m.dispose());
    else if (material) material.dispose();
  });
}

// Round 36.31: GPU-only release — the geometry buffers and
// texture images leave the GPU in every context that uploaded
// them; the parsed master (attribute arrays, decoded images,
// materials, programs) stays whole on the CPU side, so a later
// acquire re-clones with no re-parse and three.js re-uploads
// on the first render. Only ever called when no lease is live.
function releaseGpu(entry: CacheEntry): void {
  if (!entry.parsed || entry.gpuReleased) return;
  const geometries = new Set<THREE.BufferGeometry>();
  collectGeometries(entry.parsed, geometries);
  geometries.forEach(g => g.dispose());
  const textures = new Set<THREE.Texture>();
  collectTextures(entry.parsed, textures);
  textures.forEach(t => t.dispose());
  entry.gpuReleased = true;
}

// The one GPU spare: the most recently released model small
// enough to stay resident for an instant swipe-back.
let spare: CacheEntry | null = null;

// Settle a model whose last lease just went away (Round
// 36.31): it becomes the spare if it fits the cap — evicting
// the previous spare's GPU — or releases its GPU on the spot.
function settleGpu(entry: CacheEntry): void {
  if (!entry.parsed || entry.stale || entry.live > 0 || entry.waiters > 0) return;
  if (entry.gpuBytes <= SPARE_GPU_CAP) {
    // Takes the spare slot, releasing whoever held it. An
    // over-cap release (below) leaves the existing spare
    // alone — swipe Griffin away and back to the fighter
    // before it, and that fighter is still warm.
    if (spare && spare !== entry) releaseGpu(spare);
    spare = entry;
  } else {
    releaseGpu(entry);
  }
}

function maybeDispose(entry: CacheEntry): void {
  if (entry.stale && entry.parsed && entry.live === 0 && entry.waiters === 0) {
    const parsed = entry.parsed;
    entry.parsed = null;
    if (spare === entry) spare = null;
    disposeParsed(parsed);
  }
}

function evictIfNeeded(protectedUrl: string): void {
  while (entries.size > CACHE_CAP) {
    let victim: string | null = null;
    for (const key of entries.keys()) {
      if (key !== protectedUrl) {
        victim = key;
        break;
      }
    }
    if (victim === null) return;
    const entry = entries.get(victim);
    entries.delete(victim);
    if (entry) {
      entry.stale = true;
      if (spare === entry) spare = null;
      maybeDispose(entry);
    }
  }
}

function entryFor(url: string): CacheEntry {
  const existing = entries.get(url);
  if (existing) {
    // LRU touch: re-insertion moves the entry to the tail.
    entries.delete(url);
    entries.set(url, existing);
    return existing;
  }
  const entry: CacheEntry = {
    promise: Promise.resolve(null as unknown as ParsedModel),
    parsed: null,
    live: 0,
    waiters: 0,
    stale: false,
    gpuBytes: 0,
    gpuReleased: false,
  };
  entry.promise = new Promise<ParsedModel>((resolve, reject) => {
    loader.load(
      url,
      gltf => {
        entry.parsed = {
          scene: gltf.scene as THREE.Group,
          animations: gltf.animations || [],
        };
        entry.gpuBytes = estimateGpuBytes(entry.parsed);
        resolve(entry.parsed);
      },
      undefined,
      err => {
        // A failed parse leaves NO entry behind: the next
        // acquire starts a fresh parse (ModelCanvas's one-retry
        // honesty depends on this).
        if (entries.get(url) === entry) entries.delete(url);
        entry.stale = true;
        reject(err instanceof Error ? err : new Error(`model parse failed: ${url}`));
      }
    );
  });
  // An entry evicted while its parse was still in flight: once
  // the parse lands, if nobody holds or awaits it, the master
  // goes straight back out instead of lingering off the books.
  entry.promise.then(
    () => maybeDispose(entry),
    () => undefined
  );
  entries.set(url, entry);
  evictIfNeeded(url);
  return entry;
}

// Take a lease on a fighter's model: resolves with a CLONE of
// the cached parsed scene (parsing first, once, if this URL has
// never been parsed — or was evicted — this session). Call
// release() exactly when the clone leaves its scene for good.
export async function acquireModel(url: string): Promise<ModelLease> {
  const entry = entryFor(url);
  entry.waiters += 1;
  try {
    const parsed = await entry.promise;
    const scene = skeletonClone(parsed.scene) as THREE.Group;
    entry.live += 1;
    // Standing again: no longer the spare, and whatever GPU
    // release it once took is undone by the first render's
    // re-upload — clear the flag so a later release settles
    // its GPU afresh.
    if (spare === entry) spare = null;
    entry.gpuReleased = false;
    let released = false;
    return {
      scene,
      animations: parsed.animations,
      release: () => {
        if (released) return;
        released = true;
        entry.live -= 1;
        maybeDispose(entry);
        // Round 36.31: the last clone away settles the GPU —
        // spare-or-release, never a silent pile-up.
        settleGpu(entry);
      },
    };
  } finally {
    entry.waiters -= 1;
    maybeDispose(entry);
  }
}

// Parse-warming (the Round 36.22 prefetch): start the fetch +
// parse for a URL whose card is standing, so a later acquire is
// a clone instead of a main-thread parse. Never rejects — a
// failed warm costs nothing; the real load path keeps its own
// retry and portrait fallback.
export function warmModel(url: string): Promise<void> {
  if (!url) return Promise.resolve();
  const entry = entryFor(url);
  return entry.promise.then(
    () => undefined,
    () => undefined
  );
}

// Test/inspection hook: the cache's current contents.
export function modelCacheInfo(): {
  size: number;
  urls: string[];
  parsedUrls: string[];
  gpuResidentBytes: number;
  spareUrl: string | null;
} {
  const parsedUrls: string[] = [];
  let gpuResidentBytes = 0;
  for (const [url, entry] of entries) {
    if (entry.parsed) {
      parsedUrls.push(url);
      if (!entry.gpuReleased) gpuResidentBytes += entry.gpuBytes;
    }
  }
  let spareUrl: string | null = null;
  if (spare) {
    for (const [url, entry] of entries) {
      if (entry === spare) spareUrl = url;
    }
  }
  return { size: entries.size, urls: [...entries.keys()], parsedUrls, gpuResidentBytes, spareUrl };
}
